from __future__ import annotations

from dataclasses import dataclass
import re
from typing import Optional

# Key=value records, quoted values may contain spaces.
_PAIR = re.compile(r'([A-Za-z0-9_.\-]+)=("(?:[^"\\]|\\.)*"|\S+)')


@dataclass
class Line:
    """One parsed record."""

    time: str
    level: str
    msg: str
    service: str
    status: Optional[int]
    duration_ms: Optional[float]
    trace_id: str

def parse(line: str) -> Optional[Line]:
    """Return a Line, or None when the record carries no key=value pairs."""
    pairs = _pairs(line)
    if not pairs:
        return None
    return Line(
        time=_as_str(pairs.get("time", "")),
        level=_as_str(pairs.get("level", "")),
        msg=_as_str(pairs.get("msg", "")),
        service=_as_str(pairs.get("service", "")),
        status=_as_int(pairs.get("status", "")),
        duration_ms=_as_float(pairs.get("duration_ms", "")),
        trace_id=_as_str(pairs.get("trace_id", "")),
    )

def parse_all(path: str) -> list[Line]:
    """Parse every non-empty line of path, skipping records that do not match."""
